      box-shadow: 0 16px 32px rgba(63, 109, 246, 0.28);
      transition: transform 160ms ease, box-shadow 160ms ease;
    }

    button:hover {
      transform: translateY(-1px);
      box-shadow: 0 20px 36px rgba(63, 109, 246, 0.34);
    }

    button:focus-visible {
      outline: 4px solid var(--ring);
      outline-offset: 3px;
    }

    .result {
      min-height: 24px;
      margin: 0;
      color: var(--success);
      font-weight: 750;
    }

    @media (max-width: 680px) {
