    }
  </style>
</head>
<body>
  <main class="page">
    <section class="quiz-shell" id="app" aria-label="Computer languages quiz"></section>
  </main>

  <script>
    const quizQuestions = [
      {
        id: "compiled-languages",
        prompt: "Which of these are commonly compiled programming languages?",
        helpText: "Select every answer that applies. Some languages can be used in more than one way, but focus on their common production workflow.",
        choices: ["C++", "Rust", "HTML", "JavaScript"]
      },
      {
        id: "web-languages",
        prompt: "Which languages are core technologies for building web pages?",
        choices: ["HTML", "CSS", "SQL", "Assembly"]
