        id: "database-languages",
        prompt: "Which of these are commonly used to query or work with databases?",
        choices: ["SQL", "PL/SQL", "Python", "CSS"]
      }
    ];

    function Header() {
      return `
        <header class="hero">
          <p class="eyebrow">Multiple select quiz</p>
          <h1>Computer Languages</h1>
          <p class="intro">Choose all answers that fit each question, then submit your selections when you are done.</p>
        </header>
      `;
    }

    function CheckboxChoice(questionId, choice) {
