      return `
        <label class="choice" for="${inputId}">
          <input type="checkbox" id="${inputId}" name="${questionId}" value="${choice}">
          <span>${choice}</span>
        </label>
      `;
    }

    function QuestionField(question, index) {
      return `
        <div class="form-field">
          <div class="question-header">
            <span class="question-number" aria-hidden="true">${index + 1}</span>
            <div>
              <h2 class="question-title">${question.prompt}</h2>
              ${question.helpText ? `<p class="help-text">${question.helpText}</p>` : ""}
            </div>
          </div>
          <fieldset class="choices" aria-label="${question.prompt}">
            ${question.choices.map((choice) => CheckboxChoice(question.id, choice)).join("")}
