         <label class="choice" for="${inputId}">
           <input type="checkbox" id="${inputId}" name="${questionId}" value="${choice}">
           <span>${choice}</span>
         </label>
       `;
     }

     function QuestionField(question, index) {
       return `
         <div class="form-field">
           <div class="question-header">
             <span class="question-number" aria-hidden="true">${index + 1}</span>
             <div>
               <h2 class="question-title">${question.prompt}</h2>
               ${question.helpText ? `<p class="help-text">${question.helpText}</p>` : ""}
             </div>
           </div>
           <fieldset class="choices" aria-label="${question.prompt}">
             ${question.choices.map((choice) => CheckboxChoice(question.id, choice)).join("")}
           </fieldset>
         </div>
       `;
     }

     function QuizForm() {
       return `
         <form class="quiz-card" id="quiz-form">
           ${quizQuestions.map(QuestionField).join("")}
           <div class="actions">
             <button type="submit">Submit quiz</button>
             <p class="result" id="result" role="status" aria-live="polite"></p>
           </div>
         </form>
       `;
     }

     function App() {
       return Header() + QuizForm();
     }

     document.getElementById("app").innerHTML = App();

     document.getElementById("quiz-form").addEventListener("submit", (event) => {
       event.preventDefault();

       const selections = quizQuestions.reduce((count, question) => {
         return count + document.querySelectorAll(`input[name="${question.id}"]:checked`).length;
       }, 0);

       const result = document.getElementById("result");
       result.textContent = selections
         ? `Saved ${selections} selection${selections === 1 ? "" : "s"}.`
         : "Choose at least one answer to submit.";
     });
   </script>
 </body>
 </html>

')
